package com.yuegang.zhihui.ai.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.ai.infrastructure.*;import com.yuegang.zhihui.ai.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;
@Configuration(proxyBeanMethods=false)class AiConfiguration{@Bean AiGovernanceService aiGovernanceService(DataSource d){return new AiGovernanceService(d);}@Bean AiSafetyPolicy aiSafetyPolicy(DataSource d){return new AiSafetyPolicy(d);}@Bean ModelGateway modelGateway(@Value("${ygh.ai.doubao-base-url}")String b,@Value("${ygh.ai.doubao-api-key}")String k,@Value("${ygh.ai.chat-model}")String m,AiGovernanceService g){return new GovernedModelGateway(new DoubaoModelGateway(b,k,m),g);}@Bean RetrievalGateway retrievalGateway(@Value("${ygh.ai.search-base-url}")String b,@Value("${ygh.internal-request.hmac-base64}")String e,AiSafetyPolicy p){byte[]k=Base64.getDecoder().decode(e);try{return new GovernedRetrievalGateway(new HttpRetrievalGateway(b,k),p);}finally{Arrays.fill(k,(byte)0);}}@Bean CommerceToolGateway commerceToolGateway(@Value("${ygh.ai.product-base-url}")String p,@Value("${ygh.ai.order-base-url}")String o,@Value("${ygh.internal-request.hmac-base64}")String e,ObjectMapper j){byte[]k=Base64.getDecoder().decode(e);try{return new CommerceToolGateway(p,o,k,j);}finally{Arrays.fill(k,(byte)0);}}@Bean ChatService chatService(RetrievalGateway r,ModelGateway m,CommerceToolGateway t,DataSource d){return new ChatService(r,m,t,d);}@Bean AiEvaluationService aiEvaluationService(DataSource d,ChatService c){return new AiEvaluationService(d,c);}@Bean ConversationService conversationService(DataSource d){return new ConversationService(d);}@Bean AiUserResolver aiUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new AiUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
